-- Manufacturing Tools Hub - Supabase source of truth setup and seed
create table if not exists public.user_roles(id uuid primary key default gen_random_uuid(), user_id uuid unique, email text unique not null, role text not null default 'user', created_at timestamptz default now());
create table if not exists public.library_history(id uuid primary key default gen_random_uuid(), application text, table_name text, record_id text, action text, field_name text, old_value text, new_value text, user_id uuid, user_email text, created_at timestamptz default now());
create table if not exists public.cnc_materials(code text primary key,name_fr text,name_en text,name_pt text,family text,note_fr text,note_en text,note_pt text,created_by_user_id uuid,created_by_email text,updated_by_user_id uuid,updated_by_email text,updated_at timestamptz,created_at timestamptz default now());
create table if not exists public.cnc_tools(id uuid primary key default gen_random_uuid(),material_code text,tool_code text,label_fr text,label_en text,label_pt text,vc_rec numeric,fz_rec numeric,pass_rec numeric,engagement_rec numeric,created_by_user_id uuid,created_by_email text,updated_by_user_id uuid,updated_by_email text,updated_at timestamptz,created_at timestamptz default now());
create table if not exists public.cnc_machines(id uuid primary key default gen_random_uuid(),name text unique not null,n_max numeric,vf_max numeric,safety_n numeric,safety_vf numeric,created_at timestamptz default now());
create table if not exists public."CNC_calibrations"(id uuid primary key default gen_random_uuid(),material text,tool text,machine text,spindle_rpm numeric,feed_rate numeric,comments text,created_by_user_id uuid,created_by_email text,created_at timestamptz default now());
create table if not exists public.hot_supports(code text primary key,supplier text,collection text,reference text,name_fr text,name_en text,name_pt text,family text,note text,created_by_user_id uuid,created_by_email text,updated_by_user_id uuid,updated_by_email text,updated_at timestamptz,created_at timestamptz default now());
create table if not exists public.hot_foils(foil_code text primary key,manufacturer text,collection text,reference text,color text,label_fr text,label_en text,label_pt text,temperature_min numeric,temperature_rec numeric,temperature_max numeric,pressure_min numeric,pressure_rec numeric,pressure_max numeric,dwell_time_min numeric,dwell_time_rec numeric,dwell_time_max numeric,created_by_user_id uuid,created_by_email text,updated_by_user_id uuid,updated_by_email text,updated_at timestamptz,created_at timestamptz default now());
create table if not exists public.hot_machines(id uuid primary key default gen_random_uuid(),name text unique not null,temperature_max numeric,pressure_max numeric,dwell_time_max numeric,site text,created_at timestamptz default now());
create table if not exists public."Hot_Stamping_calibrations"(id uuid primary key default gen_random_uuid(),material text,foil text,machine text,temperature numeric,pressure numeric,dwell_time numeric,comments text,created_by_user_id uuid,created_by_email text,created_at timestamptz default now());
create table if not exists public.laser_materials(code text primary key,name_fr text,name_en text,name_pt text,family text,note text,sensitive boolean default false,forbidden boolean default false,created_by_user_id uuid,created_by_email text,updated_by_user_id uuid,updated_by_email text,updated_at timestamptz,created_at timestamptz default now());
create table if not exists public.laser_parameters(id uuid primary key default gen_random_uuid(),material_code text,operation text,power_percent numeric,speed_mm_s numeric,passes numeric,frequency numeric,z_offset numeric,air_assist text,quality text,created_by_user_id uuid,created_by_email text,updated_by_user_id uuid,updated_by_email text,updated_at timestamptz,created_at timestamptz default now());
create table if not exists public.laser_machines(id uuid primary key default gen_random_uuid(),name text unique not null,watt numeric,speed_max numeric,lens text,site text,created_at timestamptz default now());
create table if not exists public."Laser_calibrations"(id uuid primary key default gen_random_uuid(),material text,operation text,machine text,thickness_mm numeric,power_percent numeric,speed_mm_s numeric,passes numeric,comments text,created_by_user_id uuid,created_by_email text,created_at timestamptz default now());


-- RLS and policies
alter table public.user_roles enable row level security; alter table public.library_history enable row level security;
alter table public.cnc_materials enable row level security; alter table public.cnc_tools enable row level security; alter table public.cnc_machines enable row level security; alter table public."CNC_calibrations" enable row level security;
alter table public.hot_supports enable row level security; alter table public.hot_foils enable row level security; alter table public.hot_machines enable row level security; alter table public."Hot_Stamping_calibrations" enable row level security;
alter table public.laser_materials enable row level security; alter table public.laser_parameters enable row level security; alter table public.laser_machines enable row level security; alter table public."Laser_calibrations" enable row level security;
DO $$ DECLARE t text; BEGIN
FOREACH t IN ARRAY ARRAY['user_roles','library_history','cnc_materials','cnc_tools','cnc_machines','CNC_calibrations','hot_supports','hot_foils','hot_machines','Hot_Stamping_calibrations','laser_materials','laser_parameters','laser_machines','Laser_calibrations'] LOOP
  EXECUTE format('drop policy if exists read_all on public.%I', t);
  EXECUTE format('create policy read_all on public.%I for select to authenticated using (true)', t);
END LOOP;
END $$;
drop policy if exists user_role_insert_self on public.user_roles;
create policy user_role_insert_self on public.user_roles for insert to authenticated with check (user_id = auth.uid() and role = 'user');
drop policy if exists user_role_update_auth on public.user_roles;
create policy user_role_update_auth on public.user_roles for update to authenticated using (true) with check (true);
drop policy if exists history_insert on public.library_history;
create policy history_insert on public.library_history for insert to authenticated with check (true);
DO $$ DECLARE t text; BEGIN
FOREACH t IN ARRAY ARRAY['cnc_materials','cnc_tools','cnc_machines','CNC_calibrations','hot_supports','hot_foils','hot_machines','Hot_Stamping_calibrations','laser_materials','laser_parameters','laser_machines','Laser_calibrations'] LOOP
  EXECUTE format('drop policy if exists write_auth on public.%I', t);
  EXECUTE format('create policy write_auth on public.%I for all to authenticated using (true) with check (true)', t);
END LOOP;
END $$;
grant usage on schema public to anon, authenticated;
grant select,insert,update,delete on all tables in schema public to authenticated;
notify pgrst, 'reload schema';
